"use strict";(()=>{$(document).ready(function(){$(".plyr_video").each(function(){let o=$(this).closest("[data-plyr-video]"),e=new Plyr(this,{controls:["play","progress","mute","fullscreen"],muted:!0,autoplay:!0,loop:{active:!0}});o.find(".plyr__controls").hide(),e.on("ready",function(){e.play(),e.muted=!0}),o.find(".plyr__poster").on("click",function(){setTimeout(function(){e.restart(),e.muted=!1,o.addClass("activated"),o.find(".plyr__controls").show(),e.play(),o.find(".plyr__poster").off("click")},200)})})});$(document).ready(function(){let t=new Plyr(".plyr_video",{controls:["play","progress","mute","fullscreen"],muted:!0,autoplay:!0,loop:{active:!0}});$(".plyr__controls").hide(),t.on("ready",function(){t.play(),t.muted=!0}),$(".plyr__poster").on("click",function(){setTimeout(function(){t.restart(),t.muted=!1,$(".mammoth-hero_video").addClass("activated"),$(".plyr__controls").show(),t.play(),$(".plyr__poster").off("click")},200)})});})();
